r('POST /projects/{projectId}/assets', { tag: 'Assets', summary: 'Gera um asset do vídeo pronto: GIF (loop perfeito, ≤10 s, ≤10 MB), sticker WebP transparente, wallpaper, multimídia automotiva ou screensaver. Fila assets-derive; cache por usuário (user_id + projeto + vídeo + configuração).' + AS, auth: 'user', status: 202, idem: 'required', errors: [400, 404, 409, 422, 429] });
