// Módulo 7 — Envio por e-mail (atrás de ff_email). Links públicos /s/{token}: HMAC + validade + revogação + flag do dono.
const EM = ' Requer `ff_email`.';
r('GET /email-shares/config', { tag: 'Email', summary: 'Limites: 20 destinatários por envio, teto diário, validade de 7 dias, senha mínima.' + EM, auth: 'user', errors: [404] });
r('POST /projects/{projectId}/email', { tag: 'Email', summary: 'Envia o link (HMAC, 7 dias, senha opcional argon2id) do vídeo ou de um asset do Módulo 6 para até 20 pessoas (um e-mail por pessoa) e/ou para si. Bloqueia e-mail descartável e mensagem com link. 10/min por usuário e 30/min por IP.' + EM, auth: 'user', status: 202, idem: 'required', errors: [400, 404, 409, 422, 429] });
r('POST /catalogs/{catalogId}/email', { tag: 'Email', summary: 'B2B: um e-mail por produto (per_item) ou um único ZIP (zip). Aceita API key com catalogs:read.' + EM, auth: 'apikey', status: 202, idem: 'required', errors: [400, 404, 409, 422, 429] });
r('GET /email-shares', { tag: 'Email', summary: 'Envios do usuário (auditoria): arquivo, quantos destinatários, validade, acessos. Nunca devolve os e-mails.' + EM, auth: 'user', errors: [404] });
r('DELETE /email-shares/{shareId}', { tag: 'Email', summary: 'Revoga o link antes do prazo.' + EM, auth: 'user', status: 204, errors: [404] });
r('GET /s/{token}', { tag: 'Email', summary: 'Página pública do link (HTML sem script) ou JSON (?format=json): arquivo, remetente, validade e se pede senha.', auth: 'public', errors: [404, 429] });
r('GET /s/{token}/download', { tag: 'Email', summary: 'Download sem senha: redireciona para URL assinada de 5 min e conta o acesso (200 JSON `{url}` com `Accept: application/json`).', auth: 'public', status: 303, res: 'SignedDownload', alt: [200], errors: [401, 404, 429] });
r('POST /s/{token}/download', { tag: 'Email', summary: 'Download com senha (form ou JSON). 5 tentativas erradas por link travam por 15 min (200 JSON `{url}` com `Accept: application/json`).', auth: 'public', status: 303, res: 'SignedDownload', alt: [200], errors: [401, 404, 429] });

// Módulo 8 — Colaboração (ff_collaboration) e Timeline (ff_timeline). Permissões pela matriz (docs/modules/COLLABORATION.md).
const CO = ' Requer `ff_collaboration`.', TL = ' Requer `ff_timeline`.';
r('POST /projects/{projectId}/collaborators', { tag: 'Collaboration', summary: 'Dono convida por e-mail (editor ou viewer). Token assinado, 7 dias, uso único e preso ao e-mail convidado.' + CO, auth: 'user', status: 201, idem: 'required', errors: [403, 404, 409, 422, 429] });
r('GET /projects/{projectId}/collaborators', { tag: 'Collaboration', summary: 'Membros com papel e presença; convites pendentes só para o dono (sem e-mail).' + CO, auth: 'user', errors: [404] });
r('DELETE /projects/{projectId}/collaborators/me', { tag: 'Collaboration', summary: 'LGPD: o colaborador sai do projeto (a sessão em tempo real cai).', auth: 'user', status: 204, errors: [404] });
r('DELETE /projects/{projectId}/collaborators/{memberId}', { tag: 'Collaboration', summary: 'Dono remove um colaborador ou cancela um convite.' + CO, auth: 'user', status: 204, errors: [403, 404] });
r('POST /collab/invites/accept', { tag: 'Collaboration', summary: 'Aceita o convite (mesmo e-mail do convite; uso único).' + CO, auth: 'user', errors: [403, 404, 409, 429] });
r('GET /collab/projects', { tag: 'Collaboration', summary: 'Projetos em que sou colaborador.' + CO, auth: 'user', errors: [404] });
r('POST /collab/ws-ticket', { tag: 'Collaboration', summary: 'Ticket do WebSocket: JWT de 60 s, uso único, enviado na 1ª mensagem (nunca na URL).' + CO, auth: 'user', errors: [403, 404, 429] });
r('GET /collab/ws', { tag: 'Collaboration', summary: 'WebSocket da sala do projeto: presença, cursores, operações de timeline (permissão conferida no servidor a cada mensagem) e comentários.', auth: 'public', status: 101, errors: [] });
r('GET /projects/{projectId}/comments', { tag: 'Collaboration', summary: 'Comentários ancorados no tempo do vídeo.' + CO, auth: 'user', errors: [404] });
r('POST /projects/{projectId}/comments', { tag: 'Collaboration', summary: 'Comentar (dono, editor e viewer).' + CO, auth: 'user', status: 201, errors: [404, 429] });
r('PATCH /projects/{projectId}/comments/{commentId}', { tag: 'Collaboration', summary: 'Editar o próprio comentário; resolver/reabrir (dono e editor).' + CO, auth: 'user', errors: [403, 404] });
r('DELETE /projects/{projectId}/comments/{commentId}', { tag: 'Collaboration', summary: 'Apagar o próprio comentário (o dono apaga qualquer um).' + CO, auth: 'user', status: 204, errors: [403, 404] });
r('POST /collab/me/comments/anonymize', { tag: 'Collaboration', summary: 'LGPD: anonimiza os meus comentários (o texto fica, o autor some).', auth: 'user', errors: [] });
r('GET /projects/{projectId}/timeline', { tag: 'Timeline', summary: 'Timeline multi-track (vídeo, áudio, texto, efeitos), montada das cenas na 1ª vez.' + TL, auth: 'user', errors: [404] });
r('POST /projects/{projectId}/timeline/ops', { tag: 'Timeline', summary: 'Aplica uma operação (dono/editor; viewer → 403). Propriedade: last-write-wins; estrutural com versão velha: 409 com fork oferecido.' + TL, auth: 'user', errors: [400, 403, 404, 409, 422, 423, 429] });
r('POST /projects/{projectId}/timeline/fork', { tag: 'Timeline', summary: 'Salva a versão de quem perdeu um conflito crítico como snapshot (fork).' + TL, auth: 'user', status: 201, errors: [403, 404] });
r('GET /projects/{projectId}/timeline/snapshots', { tag: 'Timeline', summary: 'Histórico de versões: automáticas, manuais, forks e restaurações.' + TL, auth: 'user', errors: [404] });
r('POST /projects/{projectId}/timeline/snapshots', { tag: 'Timeline', summary: 'Salvar uma versão manualmente.' + TL, auth: 'user', status: 201, errors: [403, 404] });
r('POST /projects/{projectId}/timeline/snapshots/{snapshotId}/restore', { tag: 'Timeline', summary: 'Restaura uma versão (a atual é guardada antes) e avisa todos (reload).' + TL, auth: 'user', errors: [403, 404] });
r('GET /projects/{projectId}/timeline/history', { tag: 'Timeline', summary: 'Quem mudou o quê (operações e conflitos).' + TL, auth: 'user', errors: [404] });
// Módulo 9 — Transcrição (ff_transcript) e edição agêntica (ff_agent). Transcrição = dado sensível (cifrada, 90 dias, nunca em log).
const TR = ' Requer `ff_transcript`.', AG = ' Requer `ff_agent`.';
r('GET /transcript/config', { tag: 'Transcript', summary: 'Retenção, provedor de STT (opt-out de treino) e limites.' + TR, auth: 'user', errors: [404] });
r('POST /projects/{projectId}/transcript', { tag: 'Transcript', summary: 'Transcreve o vídeo atual com tempo por palavra (fila transcript-generate). 20/h por usuário.' + TR, auth: 'user', status: 202, idem: 'required', errors: [404, 409, 429] });
r('GET /projects/{projectId}/transcript', { tag: 'Transcript', summary: 'Transcrição mais recente: palavras com início/fim (ms) e cena; `outdated` se o vídeo mudou.' + TR, auth: 'user', errors: [404] });
r('POST /projects/{projectId}/transcript/edits', { tag: 'Transcript', summary: 'Edição pelo texto: apagar palavras/frases (corta o vídeo) ou substituir (TTS no ponto). Gera prévia; nada muda até aplicar.' + TR, auth: 'user', status: 202, idem: 'required', errors: [400, 404, 409, 422, 429] });
r('GET /projects/{projectId}/transcript/edits/{editId}', { tag: 'Transcript', summary: 'Estado e prévia (URL assinada) da edição.' + TR, auth: 'user', errors: [404] });
r('POST /projects/{projectId}/transcript/edits/{editId}/apply', { tag: 'Transcript', summary: 'Aplica a prévia como versão nova (cenas derivadas + vídeo novo; o anterior é mantido).' + TR, auth: 'user', idem: 'required', errors: [404, 409] });
r('DELETE /projects/{projectId}/transcript/edits/{editId}', { tag: 'Transcript', summary: 'Descarta a prévia.' + TR, auth: 'user', status: 204, errors: [404] });
r('POST /projects/{projectId}/agent/plan', { tag: 'Agent', summary: 'Comando em linguagem natural → plano em staging (registrado em agent_runs). Nada é aplicado.' + AG, auth: 'user', status: 201, idem: 'required', errors: [400, 404, 409, 429] });
r('GET /projects/{projectId}/agent/runs', { tag: 'Agent', summary: 'Histórico do agente: comando, plano, prévia e aplicação (quem/quando).' + AG, auth: 'user', errors: [404] });
r('GET /projects/{projectId}/agent/runs/{runId}', { tag: 'Agent', summary: 'Estado de uma execução do agente.' + AG, auth: 'user', errors: [404] });
r('POST /projects/{projectId}/agent/runs/{runId}/execute', { tag: 'Agent', summary: 'Renderiza a prévia do plano (fila agent-execute). 10/h por usuário.' + AG, auth: 'user', status: 202, idem: 'required', errors: [404, 422, 429] });
r('POST /projects/{projectId}/agent/runs/{runId}/apply', { tag: 'Agent', summary: 'Aplica a prévia SÓ com {"confirm": true}; cria versão nova (derived_from_scene_id).' + AG, auth: 'user', idem: 'required', errors: [404, 409, 422] });
r('DELETE /projects/{projectId}/agent/runs/{runId}', { tag: 'Agent', summary: 'Descarta a execução (não aplicada).' + AG, auth: 'user', status: 204, errors: [404, 409] });
