r('GET /seal/config', { tag: 'Seal', summary: 'Se o selo está configurado, quem assina e o texto do selo.' + SL, auth: 'user', errors: [404] });
r('POST /projects/{projectId}/seal', { tag: 'Seal', summary: 'Ativa o selo: assina o MP4 com C2PA e EMBUTE o manifest (arquivo novo; original intacto). Fila seal-apply.' + SL, auth: 'user', status: 202, idem: 'required', errors: [404, 409, 429, 503] });
r('GET /projects/{projectId}/seal', { tag: 'Seal', summary: 'Estado do selo, selo "IA com direção humana" e download (URL assinada) do vídeo selado.' + SL, auth: 'user', errors: [404] });
r('GET /projects/{projectId}/seal/verify', { tag: 'Seal', summary: 'verifySeal do vídeo selado: lê o manifest EMBUTIDO (nunca URL externa).' + SL, auth: 'user', errors: [404] });
r('POST /seal/verify', { tag: 'Seal', summary: 'Verificação pública: envie o MP4 (video/mp4, até 100 MB); o manifest C2PA embutido é lido e validado (assinatura + hash). Nada é guardado.', auth: 'public', errors: [413, 415, 429] });
r('GET /live/sessions', { tag: 'Live', summary: 'Minhas lives e o estado do consentimento avatar_live.' + LV, auth: 'user', errors: [404] });
r('POST /live/consent', { tag: 'Live', summary: 'Consentimento avatar_live (só para avatar com a própria imagem/voz).' + LV, auth: 'user', status: 201, errors: [404, 429] });
