r('POST /live/sessions', { tag: 'Live', summary: 'createLiveSession (Business): catálogo, avatar, opt-in do lojista e rótulo "IA" obrigatórios. 5/h por usuário.' + LV, auth: 'user', status: 201, idem: 'required', errors: [400, 403, 404, 422, 429] });
r('GET /live/sessions/{sessionId}', { tag: 'Live', summary: 'Live com eventos (criada, aviso de IA exibido, iniciada, encerrada) e exibições do rótulo.' + LV, auth: 'user', errors: [404] });
r('POST /live/sessions/{sessionId}/start', { tag: 'Live', summary: 'startLive: grava o aviso de IA e entra no ar (até 3 ao mesmo tempo).' + LV, auth: 'user', idem: 'required', errors: [403, 404, 409, 429] });
r('POST /live/sessions/{sessionId}/stop', { tag: 'Live', summary: 'stopLive.' + LV, auth: 'user', idem: 'required', errors: [404, 409, 429] });
